def parse_music(music_string: str) -> List[int]:
    """Parse a string of musical notes in ASCII format and return a list of integers representing the beats each note lasts.

    Legend:
    'o' - whole note, 4 beats
    'o|' - half note, 2 beats
    '.|' - quarter note, 1 beat

    >>> parse_music('o o| .| o| o| .| .| .| .| o o')
    [4, 2, 1, 2, 2, 1, 1, 1, 1, 4, 4]
    """
    beats = []
    notes = music_string.split()
    for note in notes:
        if note == 'o':
            beats.append(4)
        elif note == 'o|':
            beats.append(2)
        elif note == '.|':
            beats.append(1)
    return beats
